// GENERATED by build-vite-app.py.
// A REGISTRY rather than one merged table. Merging every stroke path would
// work — the kana and kanji key sets are disjoint — but each module would then
// download ~100 KB of paths it never draws, undoing the code-splitting that
// keeps first load at 49 KB. Each module imports its own data file, that file
// registers on load, and the engine reads the merged table at render time.
export const STROKES = {};
export function registerStrokes(table) { Object.assign(STROKES, table); }
